 function configFields(config){return Object.entries(config||{}).map(([key,value])=>field(configTitle(key),'cfg:'+key,Array.isArray(value)?value.join('\n'):value,Array.isArray(value)?{textarea:true,wide:true,rows:4}:key==='priority'?{select:['low','normal','high','urgent'].map(v=>[v,deps.t('status.'+v)])}:{type:'number',min:key==='threshold_hours'?0:1,max:key==='threshold_hours'?8760:key==='min_count'?10000:366,required:true})).join('');}
 function rowMessage(value){const message=String(value||'');if(!message)return '';if(state.lang==='en')return message;let match;if((match=message.match(/nonnegative ([A-Z]{3}) decimal with at most (\d+) fractional digits/)))return text(message,'请输入非负 '+match[1]+' 金额，最多 '+match[2]+' 位小数。','Nichtnegativen '+match[1]+'-Betrag mit höchstens '+match[2]+' Nachkommastellen eingeben。',match[1]+'の0以上の金額を小数'+match[2]+'桁以内で入力してください。');if(message.startsWith('CSV sources refresh'))return deps.localeData?.errors?.CSV_UPLOAD_REQUIRED?.[state.lang]||message;if(message.includes('data source is paused'))return deps.localeData?.errors?.SOURCE_PAUSED?.[state.lang]||message;if(message.includes('Execution failed.'))return text(message,'执行失败，可从已保存的检查点重试。','Ausführung fehlgeschlagen. Vom gespeicherten Prüfpunkt erneut versuchen.','実行に失敗しました。保存済みの地点から再試行できます。');if(message.includes('Duplicate external ID'))return text(message,'文件中外部编号重复，仅首条有效记录可导入。','Doppelte externe Referenz. Nur die erste gültige Zeile wird importiert.','外部参照IDが重複しています。最初の有効行のみ取り込みます。');if(message.includes('timezone'))return text(message,'日期时间必须包含明确时区，例如 Z 或 +08:00。','Datum und Uhrzeit benötigen eine Zeitzone, z. B. Z oder +08:00.','日時にはZや+08:00などのタイムゾーンが必要です。');if(message.includes('date')||message.includes('Date'))return text(message,'请检查来源日期是否有效。','Bitte das Quelldatum prüfen.','ソースの日付を確認してください。');if(message.includes('status'))return text(message,'请使用支持的订单或付款状态。','Bitte einen unterstützten Bestell- oder Zahlungsstatus verwenden.','対応する注文・支払状態を指定してください。');return text(message,'请检查必填值、日期、币种及金额格式。','Pflichtwerte, Datums-, Währungs- und Betragsformat prüfen.','必須項目・日付・通貨・金額形式を確認してください。');}
