 function localCollector(){const csvSources=sources.filter(source=>['csv_generic','shopify_csv'].includes(source.kind));return panel(text('Local folder sync','本地文件夹同步','Lokale Ordnersynchronisierung','ローカルフォルダー同期'),'<div class="wb-body"><p class="wb-muted">'+esc(text('Run the collector on your computer to import CSV exports on a schedule. The cloud workspace cannot read your local disk directly. Excel files must be exported as CSV.','在你的电脑运行采集器，定时导入 CSV 导出文件。云端工作区不会直接读取本地磁盘；Excel 文件需先导出为 CSV。','Den Collector auf Ihrem Computer ausführen, um CSV-Exporte regelmäßig zu importieren. Die Cloud liest lokale Laufwerke nicht direkt. Excel zuvor als CSV exportieren.','PC上でコレクターを実行し、CSVを定期的に取り込みます。クラウドからローカルディスクは直接読み取れません。ExcelはCSVへ変換してください。'))+'</p><div class="wb-toolbar">'+field(l('source'),'collector_source','',{select:options(csvSources,l('select'))})+'<a class="button" href="/admin/assets/local-source-sync.mjs" download="local-source-sync.mjs">'+esc(text('Download collector','下载本地采集器','Collector herunterladen','コレクターをダウンロード'))+' ↓</a></div><pre class="wb-code" data-op-collector-command>'+esc(collectorCommand('SOURCE_ID'))+'</pre><p class="wb-muted">'+esc(text('Node.js required. Provide the workspace password only through the GYUTRON_ADMIN_PASSWORD environment variable.','需要 Node.js；工作区密码仅通过环境变量 GYUTRON_ADMIN_PASSWORD 提供。','Node.js erforderlich. Das Passwort ausschließlich über die Umgebungsvariable GYUTRON_ADMIN_PASSWORD angeben.','Node.jsが必要です。パスワードは環境変数GYUTRON_ADMIN_PASSWORDでのみ指定します。'))+'</p></div>');}
