 async function previewImport(form,mapping){if(busy)return;busy=true;const current=context;const values=Object.fromEntries(new FormData(form));if(!mapping)mapping=Object.fromEntries([...form.querySelectorAll('[name^="manual:"]')].filter(input=>input.value).map(input=>[input.name.slice(7),input.value]));setFormBusy(form,true);try{csvDraft=values.csv;sourceDraft=values.source_id;entityDraft=values.entity;formatDraft=values.format;const result=await get('imports/preview',{method:'POST',body:{source_id:sourceDraft,entity:entityDraft,format:formatDraft,csv:csvDraft,...(mapping?{mapping}:{})}});if(current!==context)return;const oldPreview=preview;preview=result.data;if(oldPreview?.batch?.status==='preview'){try{await get('imports/'+encodeURIComponent(idOf(oldPreview.batch))+'/discard',{method:'POST',body:{version:oldPreview.batch.version}});}catch(error){toast(error.message,true);}}page.querySelector('[data-op-preview]').innerHTML=previewPanel(preview);dirty=true;page.querySelectorAll('.wb-stepbar li').forEach((el,index)=>el.classList.toggle('is-current',index===1));}catch(error){showFormError(form,error);}finally{busy=false;setFormBusy(form,false);}}
